    if (config->GetKind_Linear_Solver_Inner() == LINEAR_SOLVER_INNER::BCGSTAB) {
      inner_solver->BCGSTAB_LinSolver(u, v, mat_vec, *normal_prec, sqrt(SolverTol), MaxIter, res, false, config);
    } else {
      const auto smooth_iter = static_cast<unsigned long>(std::round(fmax(2, sqrt(MaxIter))));
      inner_solver->Smoother_LinSolver(u, v, mat_vec, *normal_prec, 0, smooth_iter, res, false, config);
    }
  };
  nested_prec = new CAbstractPreconditioner<ScalarType>(f);
}
const auto* precond = nested ? nested_prec : normal_prec;

/*--- Solve system. ---*/

ScalarType residual = 0.0;

switch (KindSolver) {
  case BCGSTAB:
    IterLinSol = BCGSTAB_LinSolver(*LinSysRes_ptr, *LinSysSol_ptr, mat_vec, *precond, SolverTol, MaxIter, residual,
                                   ScreenOutput, config);
    break;
  case FGMRES:
    IterLinSol = FGMRES_LinSolver(*LinSysRes_ptr, *LinSysSol_ptr, mat_vec, *precond, SolverTol, MaxIter, residual,
                                  ScreenOutput, config);
    break;

/*!\brief LINEAR_SOLVER
 *  \n DESCRIPTION: Linear solver for the implicit, mesh deformation, or discrete adjoint systems \n OPTIONS: see \link Linear_Solver_Map \endlink \n DEFAULT: FGMRES \ingroup Config*/
addEnumOption("LINEAR_SOLVER", Kind_Linear_Solver, Linear_Solver_Map, FGMRES);
/*!\brief LINEAR_SOLVER_PREC
 *  \n DESCRIPTION: Preconditioner for the Krylov linear solvers \n OPTIONS: see \link Linear_Solver_Prec_Map \endlink \n DEFAULT: LU_SGS \ingroup Config*/
addEnumOption("LINEAR_SOLVER_PREC", Kind_Linear_Solver_Prec, Linear_Solver_Prec_Map, ILU);
/* DESCRIPTION: Minimum error threshold for the linear solver for the implicit formulation */
addDoubleOption("LINEAR_SOLVER_ERROR", Linear_Solver_Error, 1E-6);
/* DESCRIPTION: Maximum number of iterations of the linear solver for the implicit formulation */
addUnsignedLongOption("LINEAR_SOLVER_ITER", Linear_Solver_Iter, 10);
/*!\brief LINEAR_SOLVER
 *  \n DESCRIPTION: Linear solver for the poisson system \n OPTIONS: see \link Linear_Solver_Map \endlink \n DEFAULT: FGMRES \ingroup Config*/
addEnumOption("POISSON_LINEAR_SOLVER", Kind_Poisson_Linear_Solver, Linear_Solver_Map, FGMRES);
/*!\brief LINEAR_SOLVER_PREC
 *  \n DESCRIPTION: Preconditioner for the Krylov linear solvers \n OPTIONS: see \link Linear_Solver_Prec_Map \endlink \n DEFAULT: LU_SGS \ingroup Config*/
addEnumOption("POISSON_LINEAR_SOLVER_PREC", Kind_Poisson_Linear_Solver_Prec, Linear_Solver_Prec_Map, ILU);
/* DESCRIPTION: Minimum error threshold for the poisson linear solver */
addDoubleOption("POISSON_LINEAR_SOLVER_ERROR", Poisson_Linear_Solver_Error, 1E-6);
/* DESCRIPTION: Maximum number of iterations of the poisson linear solver */
addUnsignedLongOption("POISSON_LINEAR_SOLVER_ITER", Poisson_Linear_Solver_Iter, 10);
/* DESCRIPTION: Fill in level for the ILU preconditioner */
addUnsignedShortOption("LINEAR_SOLVER_ILU_FILL_IN", IluOptions.FillIn, 0);
/* DESCRIPTION: Use level scheduling for OMP parallelization of the ILU preconditioner */
addBoolOption("LINEAR_SOLVER_ILU_LEVEL_SCHEDULING", IluOptions.LevelScheduling, false);
/* DESCRIPTION: Number of colored Gauss-Seidel sweeps used to build the GPU ILU factorization */
addUnsignedShortOption("LINEAR_SOLVER_ILU_GPU_SWEEPS", IluOptions.GPUSweeps, 2);
/* DESCRIPTION: Maximum number of iterations of the linear solver for the implicit formulation */
addUnsignedLongOption("LINEAR_SOLVER_RESTART_FREQUENCY", Linear_Solver_Restart_Frequency, 10);
/* DESCRIPTION: Number of vectors used for deflated restarts */
addUnsignedLongOption("LINEAR_SOLVER_RESTART_DEFLATION", Linear_Solver_Restart_Deflation, 4);
/* DESCRIPTION: Relaxation factor for iterative linear smoothers (SMOOTHER_ILU/JACOBI/LU-SGS/LINELET) */
addDoubleOption("LINEAR_SOLVER_SMOOTHER_RELAXATION", Linear_Solver_Smoother_Relaxation, 1.0);
/* DESCRIPTION: Custom number of threads used for additive domain decomposition for ILU and LU_SGS (0 is "auto"). */
addUnsignedLongOption("LINEAR_SOLVER_PREC_THREADS", Linear_Solver_Prec_Threads, 0);
/* DESCRIPTION: Use an inner linear solver. */
addEnumOption("LINEAR_SOLVER_INNER", Kind_Linear_Solver_Inner, Inner_Linear_Solver_Map, LINEAR_SOLVER_INNER::NONE);
/* DESCRIPTION: Relaxation of the pressure corrections for the SIMPLE algorithm */
addDoubleOption("RELAXATION_FACTOR_PRESSURE", SIMPLE_Options.Relaxation_Factor_Pressure, 1.0);
/* DESCRIPTION: Removal factor for the transient term in the momentum coefficients for the poisson solver. */
addDoubleOption("TRANSIENT_TERM_REMOVAL_FACTOR", SIMPLE_Options.Transient_Term_Removal_Factor, 0.0);
/*!\DESCRIPTION: Automatically compute relaxation factors for flow corrections in the SIMPLE algorithm */
addBoolOption("USE_AUTOMATIC_RELAXATION_FACTORS", SIMPLE_Options.AutomaticRelaxationFactors, false);

/*--- The NK solves are expensive, the tolerance is relaxed while the residuals are high. ---*/

Scalar toleranceFactor = 1.0;

if (!startupPeriod && tolRelaxFactor > 1 && fullTolResidual < 0.0) {
  SU2_OMP_SAFE_GLOBAL_ACCESS(firstResidual = max(firstResidual, residual);)
  su2double x = (residual - firstResidual) / fullTolResidual;
  toleranceFactor = 1.0 + (tolRelaxFactor-1)*max(0.0, 1.0-SU2_TYPE::GetValue(x));
}

/*--- Solve for the solution update. ---*/

auto iter = config->GetLinear_Solver_Iter();
Scalar eps = SU2_TYPE::GetValue(config->GetLinear_Solver_Error());

auto& linSysSol = GetSolutionVec(solvers[FLOW_SOL]->LinSysSol);

if (startupPeriod) {
  iter = Preconditioner_impl(LinSysRes, linSysSol, iter, eps);
} else {
  ComputeFinDiffStep();

  eps *= toleranceFactor;
  if (useDeflation) {
    iter = LinSolver.FGCRODR_LinSolver(LinSysRes, linSysSol, CMatrixFreeProductWrapper(this),
                                       CPreconditionerWrapper(this), eps, iter, eps, false, config);
  } else {
    iter = LinSolver.FGMRES_LinSolver(LinSysRes, linSysSol, CMatrixFreeProductWrapper(this),
                                      CPreconditionerWrapper(this), eps, iter, eps, false, config);
  }
  /*--- Scale back the residual to trick the CFL adaptation. ---*/
  eps /= toleranceFactor;
}
SetSolutionResult(solvers[FLOW_SOL]->LinSysSol);

BEGIN_SU2_OMP_SAFE_GLOBAL_ACCESS {
  solvers[FLOW_SOL]->SetIterLinSolver(iter);
  solvers[FLOW_SOL]->SetResLinSolver(eps);

  if (!startupPeriod && autoRelaxation) {
    const su2double adaptTol = config->GetCFL_Adapt() ? config->GetCFL_AdaptParam(4) : 0;
    if (eps > fmax(config->GetLinear_Solver_Error(), adaptTol)) {
      nkRelaxation *= 0.9;
    } else if (eps < 0.9 * fmax(config->GetLinear_Solver_Error(), adaptTol)) {
      nkRelaxation = fmin(fmax(nkRelaxation * 1.05, 0.05), 1);
    }
  }
}
END_SU2_OMP_SAFE_GLOBAL_ACCESS

/// TODO: Clever back-tracking and CFL adaptation based on residual reduction.

/*--- Update solution. ---*/

solvers[FLOW_SOL]->CompleteImplicitIteration(geometry, solvers, config);

/*--- Call the various post processings. ---*/

 * \brief The preconditioner on its own, or a nested solve with the approximate Jacobian.
 */
inline unsigned long PreconditionerApply(const CSysVector<MixedScalar>& u, CSysVector<MixedScalar>& v,
                                         unsigned long iters, Scalar& eps) const {
  const auto inner_solver = config->GetKind_Linear_Solver_Inner();

  if (iters == 0 || (iters == 1 && inner_solver == LINEAR_SOLVER_INNER::SMOOTHER)) {
    (*preconditioner)(u, v);
    return 0;
  }
  auto product = CSysMatrixVectorProduct<MixedScalar>(solvers[FLOW_SOL]->Jacobian, geometry, config);
  v = MixedScalar(0.0);
  MixedScalar eps_t = eps;
  switch (inner_solver) {
    case LINEAR_SOLVER_INNER::NONE:
      iters = solvers[FLOW_SOL]->System.FGMRES_LinSolver(u, v, product, *preconditioner, eps, iters, eps_t, false, config);
      break;
    case LINEAR_SOLVER_INNER::BCGSTAB:
      iters = solvers[FLOW_SOL]->System.BCGSTAB_LinSolver(u, v, product, *preconditioner, eps, iters, eps_t, false, config);
      break;
    case LINEAR_SOLVER_INNER::SMOOTHER:
      iters = solvers[FLOW_SOL]->System.Smoother_LinSolver(u, v, product, *preconditioner, 0, iters, eps_t, false, config);
      break;
  }
  eps = eps_t;
  return iters;
}

void CScalarSolver<VariableType>::ImplicitEuler_Iteration(CGeometry* geometry, CSolver** solver_container,
                                                          CConfig* config) {
  SU2_ZONE_SCOPED

  PrepareImplicitIteration(geometry, solver_container, config);

  /*--- Solve or smooth the linear system. ---*/

  SU2_OMP_FOR_(schedule(static, OMP_MIN_SIZE) SU2_NOWAIT)
  for (unsigned long iPoint = nPointDomain; iPoint < nPoint; iPoint++) {
    LinSysRes.SetBlock_Zero(iPoint);
    LinSysSol.SetBlock_Zero(iPoint);
  }
  END_SU2_OMP_FOR

  auto iter = System.Solve(Jacobian, LinSysRes, LinSysSol, geometry, config);

  BEGIN_SU2_OMP_SAFE_GLOBAL_ACCESS {
    SetIterLinSolver(iter);
    SetResLinSolver(System.GetResidual());
  }
  END_SU2_OMP_SAFE_GLOBAL_ACCESS

  CompleteImplicitIteration(geometry, solver_container, config);
}
